<?php
// Deploy this single file as https://nonceblox.com/interview-schedule.php.
// Point RESUMEIQ_SCHEDULING_API_URL to the public ResumeIQ endpoint.
$apiUrl=getenv('RESUMEIQ_SCHEDULING_API_URL')?:'https://resume.nonceblox.com/public_interview_api.php';$token=trim((string)($_GET['token']??$_POST['token']??''));$error='';$data=[];
function scheduleApi(string $url,string $token,?int $slotId=null): array{if(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https')throw new RuntimeException('Scheduling service is not configured.');$curl=curl_init();$options=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_HTTPHEADER=>['Accept: application/json']];if($slotId===null){$options[CURLOPT_URL]=$url.'?token='.rawurlencode($token);}else{$options[CURLOPT_URL]=$url;$options[CURLOPT_POST]=true;$options[CURLOPT_HTTPHEADER]=['Accept: application/json','Content-Type: application/json'];$options[CURLOPT_POSTFIELDS]=json_encode(['token'=>$token,'slot_id'=>$slotId]);}curl_setopt_array($curl,$options);$body=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_HTTP_CODE);$networkError=curl_error($curl);curl_close($curl);if($body===false||$networkError!==''||$status>=500)throw new RuntimeException('Scheduling service is temporarily unavailable.');$decoded=json_decode((string)$body,true);if(!is_array($decoded))throw new RuntimeException('Scheduling service returned an invalid response.');return $decoded;}
if(!preg_match('/^[A-Za-z0-9_-]{40,60}$/',$token))$error='This interview link is invalid.';else try{$data=$_SERVER['REQUEST_METHOD']==='POST'?scheduleApi($apiUrl,$token,(int)($_POST['slot_id']??0)):scheduleApi($apiUrl,$token);if(empty($data['ok']))$error=$data['error']??'This interview link is unavailable.';}catch(Throwable $e){$error=$e->getMessage();}
$slotsByDay=[];foreach($data['slots']??[] as $slot)$slotsByDay[substr($slot['starts_at'],0,10)][]=$slot;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Schedule your interview | NonceBlox</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><style>:root{--ink:#171722;--muted:#716d7b;--line:#e8e5ed;--violet:#6843e9;--soft:#f7f4ff;--green:#11845a}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:32px 16px;background:radial-gradient(circle at 85% 8%,#ece6ff,transparent 30%),#f6f6f9;font-family:Inter,Arial,sans-serif;color:var(--ink)}main{width:min(760px,100%);margin:auto}.brand{font-size:21px;font-weight:800;margin-bottom:22px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 24px 70px #261d4812;overflow:hidden}.hero{padding:36px;background:linear-gradient(135deg,#fff,#f7f3ff);border-bottom:1px solid var(--line)}.kicker{font-size:11px;color:var(--violet);font-weight:700;text-transform:uppercase;letter-spacing:.1em}h1{font-size:32px;letter-spacing:-.04em;margin:10px 0}p{color:var(--muted);line-height:1.65}.content{padding:30px 36px}.day{margin-bottom:24px}.day h2{font-size:14px}.slots{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.slot input{position:absolute;opacity:0}.slot span{display:block;padding:12px;text-align:center;border:1px solid var(--line);border-radius:8px;font-weight:600;cursor:pointer}.slot input:checked+span{border-color:var(--violet);background:var(--soft);color:var(--violet)}.actions{display:flex;justify-content:flex-end;padding-top:20px;border-top:1px solid var(--line)}button{border:0;border-radius:9px;padding:13px 18px;background:var(--violet);color:#fff;font-weight:700}.notice,.success{padding:20px;border-radius:10px}.notice{background:#fff1f3;color:#a13d50}.success{background:#ecfaf4;color:var(--green)}.success strong{display:block;font-size:20px;margin-bottom:7px}@media(max-width:620px){.hero,.content{padding:24px}.slots{grid-template-columns:repeat(2,1fr)}h1{font-size:27px}}</style></head><body><main><div class="brand">NonceBlox</div><section class="card"><header class="hero"><div class="kicker">Interview scheduling</div><h1><?=htmlspecialchars(($data['confirmed']??false)?'Interview confirmed':'Choose your time')?></h1><?php if(!$error&&!empty($data['candidate'])):?><p>Hello <?=htmlspecialchars($data['candidate'])?>. Choose one available slot for the <strong><?=htmlspecialchars($data['job'])?></strong> interview. Times are shown in <?=htmlspecialchars($data['timezone'])?>.</p><?php endif?></header><div class="content"><?php if($error):?><div class="notice"><?=htmlspecialchars($error)?></div><?php elseif(!empty($data['confirmed'])):?><div class="success"><strong>Your interview is confirmed.</strong><?=htmlspecialchars(date('l, d F Y \a\t g:i A',strtotime($data['confirmed_at'])))?> (<?=htmlspecialchars($data['timezone'])?>). This one-time link is now closed.</div><?php elseif(!empty($data['expired'])):?><div class="notice">This one-time interview link has expired. Please contact the hiring team if you need help.</div><?php elseif(!$slotsByDay):?><div class="notice">No interview times are currently available.</div><?php else:?><form method="post"><input type="hidden" name="token" value="<?=htmlspecialchars($token)?>"><?php foreach($slotsByDay as $date=>$slots):?><section class="day"><h2><?=htmlspecialchars(date('l, d F',strtotime($date)))?></h2><div class="slots"><?php foreach($slots as $slot):?><label class="slot"><input type="radio" name="slot_id" value="<?=(int)$slot['id']?>" required><span><?=htmlspecialchars(date('g:i A',strtotime($slot['starts_at'])))?></span></label><?php endforeach?></div></section><?php endforeach?><div class="actions"><button onclick="return confirm('Confirm this interview time? You cannot change it from this link afterwards.')">Confirm interview time</button></div></form><?php endif?></div></section></main></body></html>
